import { Box } from '@mui/material'
import { useSortable } from '@dnd-kit/sortable'
import { useCallback } from 'react'
import type { MouseEventHandler, ReactNode, TouchEventHandler } from 'react'

export interface ProjectCardDragInteractions {
    onClick: MouseEventHandler<HTMLElement>
    onContextMenu: MouseEventHandler<HTMLElement>
    onTouchEnd: TouchEventHandler<HTMLElement>
    onTouchStart: TouchEventHandler<HTMLElement>
}

interface ProjectCardDragContainerProps {
    cardId: string
    cardPath: string
    children: ReactNode
    interactions: ProjectCardDragInteractions
    isBodyOpen: boolean
    isSelected: boolean
    onCardElementChange: (element: HTMLDivElement | null) => void
}

/** Lightweight sortable adapter that updates only card drag DOM around stable card content. */
export function ProjectCardDragContainer(props: ProjectCardDragContainerProps) {
    const {cardId, cardPath, children, interactions, isBodyOpen, isSelected, onCardElementChange} = props
    const { onClick, onContextMenu, onTouchEnd, onTouchStart } = interactions
    const sortable = useSortable({ id: cardPath })
    const { attributes, isDragging, listeners, setActivatorNodeRef, setNodeRef, transform, transition } = sortable
    const dragTranslation = transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : ''
    const transformStyle = `${dragTranslation}${isDragging ? ' rotate(2deg)' : ''}`.trim() || undefined
    const setCardElement = useCallback((element: HTMLDivElement | null) => {
        setNodeRef(element)
        onCardElementChange(element)
    }, [onCardElementChange, setNodeRef])

    return (
        <Box
            data-card-path={cardPath}
            data-selected={isSelected ? 'true' : undefined}
            onContextMenu={onContextMenu}
            onTouchCancel={onTouchEnd}
            onTouchEnd={onTouchEnd}
            onTouchMove={onTouchEnd}
            onTouchStart={onTouchStart}
            ref={setCardElement}
            sx={{
                bgcolor: 'background.paper',
                border: 1,
                borderColor: isSelected ? 'primary.main' : 'divider',
                borderRadius: 1.25,
                boxShadow: isDragging ? 'var(--md2-card-drag-shadow)' : 'var(--md2-card-shadow)',
                opacity: isDragging ? 0 : 1,
                overflow: 'hidden',
                position: 'relative',
                transform: transformStyle,
                transition,
                '&:hover': { borderColor: 'text.disabled', boxShadow: 'var(--md2-card-hover-shadow)' },
            }}
        >
            <Box
                {...attributes}
                {...listeners}
                aria-expanded={isBodyOpen}
                aria-haspopup="dialog"
                aria-label={`Drag ${cardId}`}
                component="button"
                onClick={onClick}
                ref={setActivatorNodeRef}
                sx={{
                    bgcolor: 'transparent',
                    border: 0,
                    cursor: isDragging ? 'grabbing' : 'pointer',
                    inset: 0,
                    position: 'absolute',
                    touchAction: 'none',
                    zIndex: 1,
                    '&:focus-visible': { outline: '2px solid', outlineColor: 'primary.main', outlineOffset: -2 },
                }}
                type="button"
            />
            {children}
        </Box>
    )
}

import { Box } from '@mui/material'
import { DndContext, DragOverlay, PointerSensor, closestCorners, useSensor, useSensors } from '@dnd-kit/core'
import type { DragEndEvent, DragMoveEvent, DragStartEvent } from '@dnd-kit/core'
import { useCallback, useEffect, useRef, useState } from 'react'
import type { RefObject } from 'react'
import { buildCardColumns } from '../../data/card_ordering'
import type { CardTypeConfig, StateConfig } from '../../data/data_types'
import { dataService } from '../../services/data/data_service'
import { dialogService } from '../../services/dialog_service'
import { openFilesService } from '../../services/open_files_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { telemetryService } from '../../services/telemetry/telemetry_service'
import { AffectsEditorDialog } from './affects_editor_dialog'
import { CardActionPopupHost } from '../actions/card_action_popup_host'
import { CardBodyPopover } from './card_body_popover'
import { cardBodyPopoverService } from './card_body_popover_service'
import { CardColumn } from './card_column'
import { CardDragOverlay } from './card_drag_overlay'
import { cardDragDropService } from './card_drag_drop_service'
import { resolveCardDragEvent } from './card_drag'
import { CardViewScrollZones } from './card_view_scroll_zones'
import { useCardViewColumns } from './use_card_view_columns'

const DRAG_ACTIVATION_DISTANCE = 2
interface CardViewProps {
    cardTypes: CardTypeConfig[]
    isMobile: boolean
    scrollContainerRef: RefObject<HTMLDivElement | null>
    states: StateConfig[]
    statusColors: Map<string, string>
}

async function runCardEdit(action: () => unknown, fallbackMessage: string) {
    try {
        await action()
    } catch (error) {
        dialogService.error(error, { fallbackMessage })
    }
}

function currentCardColumns(states: StateConfig[]) {
    const cards = dataService.getState().snapshot?.activeCards ?? []

    return buildCardColumns(cards, states)
}

/** Card view: status columns of draggable cards with card-anchored body popup access. */
export function CardView(props: CardViewProps) {
    const {
        cardTypes,
        isMobile,
        scrollContainerRef,
        states,
        statusColors,
    } = props
    const columns = useCardViewColumns(states)
    const [openAffectsPath, setOpenAffectsPath] = useState<string | null>(null)
    const rootElementRef = useRef<HTMLDivElement>(null)
    const missingRootReportedRef = useRef(false)
    const wasVisibleRef = useRef<boolean | null>(null)
    const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: DRAG_ACTIVATION_DISTANCE } }))

    const handleOpenAffects = (path: string) => {
        setOpenAffectsPath(path)
    }

    const handleCloseAffects = () => {
        setOpenAffectsPath(null)
    }

    const clearActiveCard = useCallback(() => {
        cardDragDropService.endDrag()
    }, [])

    useEffect(() => {
        const updateVisibility = () => {
            const rootElement = rootElementRef.current
            if (!rootElement) {
                if (!missingRootReportedRef.current) {
                    missingRootReportedRef.current = true
                    dialogService.error(new Error('Missing card view root element'), {fallbackMessage: 'Card view could not be displayed'})
                }
                return
            }

            const isVisible = workspaceViewService.getSnapshot().viewMode === 'cards'
            rootElement.style.display = isVisible ? 'flex' : 'none'
            if (wasVisibleRef.current === isVisible) return

            wasVisibleRef.current = isVisible
            if (isVisible) return

            queueMicrotask(() => {
                cardBodyPopoverService.close()
                setOpenAffectsPath((currentPath) => currentPath === null ? currentPath : null)
                clearActiveCard()
            })
        }

        updateVisibility()
        workspaceViewService.addEventListener('changed', updateVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateVisibility)
    }, [clearActiveCard])

    useEffect(() => () => cardBodyPopoverService.close(), [])

    const handleDragStart = useCallback((event: DragStartEvent) => {
        cardDragDropService.startDrag(
            String(event.active.id),
            event.active.rect.current.initial?.height ?? null,
            event.active.rect.current.initial?.width ?? null,
        )
    }, [])

    const handleDragMove = useCallback((event: DragMoveEvent) => {
        const { active, over } = event
        if (!over) {
            cardDragDropService.setDropPreview(null)
            return
        }

        const dragColumns = currentCardColumns(states)
        const drop = resolveCardDragEvent(dragColumns, event)
        const sourceColumn = dragColumns.find((column) => column.cards.some((card) => card.path === String(active.id)))
        const dropPreview = drop && sourceColumn?.status !== drop.targetStatus ? drop : null
        cardDragDropService.setDropPreview(dropPreview)
    }, [states])

    const handleDragEnd = useCallback((event: DragEndEvent) => {
        const { active, over } = event
        const drop = over ? resolveCardDragEvent(currentCardColumns(states), event) : null
        clearActiveCard()
        const path = String(active.id)
        if (drop) void runCardEdit(() => dataService.cards.moveCard(path, drop.targetStatus, drop.targetIndex), `Card move failed: ${path}`)
    }, [clearActiveCard, states])

    const handleOpenInFileMode = (path: string) => {
        cardBodyPopoverService.close()
        workspaceViewService.selectPath(path)
        void runCardEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)
        workspaceViewService.setViewMode('text')
        telemetryService.trackEvent('navigation')
    }

    const handleDeleteCard = async (path: string) => {
        try {
            await dataService.cards.deleteCard(path)
            workspaceViewService.clearSelectedPath(path)
            cardBodyPopoverService.closePath(path)
            if (openAffectsPath === path) handleCloseAffects()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Card delete failed: ${path}` })
            throw error
        }
    }

    const handleTitleChange = (path: string, title: string) => {
        dataService.cards.updateCardTitle(path, title).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: `Title update failed: ${path}` })
        })
    }

    const handleTogglePolicy = (path: string, policyKey: string) => {
        void runCardEdit(() => dataService.cards.toggleCardPolicy(path, policyKey), `Policy toggle failed: ${path}`)
    }

    const handleAffectsChange = (path: string, affects: string[]) => {
        void runCardEdit(() => dataService.cards.updateCardAffects(path, affects), `Affects update failed: ${path}`)
    }

    return (
        <Box
            ref={rootElementRef}
            sx={{ bgcolor: 'background.default', display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden', position: 'relative' }}
        >
            <DndContext
                collisionDetection={closestCorners}
                onDragCancel={clearActiveCard}
                onDragEnd={handleDragEnd}
                onDragMove={handleDragMove}
                onDragStart={handleDragStart}
                sensors={sensors}
            >
                <Box
                    aria-label="Card columns"
                    sx={{
                        alignItems: 'flex-start',
                        display: 'flex',
                        flex: 1,
                        flexDirection: isMobile ? 'column' : 'row',
                        gap: 2,
                        height: '100%',
                        overflowX: isMobile ? 'hidden' : 'auto',
                        overflowY: 'auto',
                        p: isMobile ? 0 : 2.5,
                    }}
                >
                    {columns.map((column) => (
                        <CardColumn
                            key={column.status}
                            cardTypes={cardTypes}
                            column={column}
                            isMobile={isMobile}
                            onDeleteCard={handleDeleteCard}
                            onOpenInFileMode={handleOpenInFileMode}
                            onTitleChange={handleTitleChange}
                            onTogglePolicy={handleTogglePolicy}
                        />
                    ))}
                </Box>
                {isMobile && <CardViewScrollZones scrollContainerRef={scrollContainerRef} />}
                <DragOverlay>
                    <CardDragOverlay cardTypes={cardTypes} />
                </DragOverlay>
                <CardBodyPopover
                    cardTypes={cardTypes}
                    isMobile={isMobile}
                    onDeleteCard={handleDeleteCard}
                    onOpenAffects={handleOpenAffects}
                    onOpenInFileMode={handleOpenInFileMode}
                    statusColors={statusColors}
                    visible
                />
                <AffectsEditorDialog
                    cardPath={openAffectsPath}
                    onClose={handleCloseAffects}
                    onSave={handleAffectsChange}
                />
                <CardActionPopupHost />
            </DndContext>
        </Box>
    )
}

import { Box, Chip, IconButton, Paper, Tooltip, Typography } from '@mui/material'
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import Plus from 'mdi-material-ui/Plus'
import { useCallback, useSyncExternalStore } from 'react'
import type { ReactNode } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { requestOpenNewCardDialog } from '../project_command_events'
import { CardColumnEndDropTarget } from './card_column_end_drop_target'
import { cardDragDropService } from './card_drag_drop_service'
import { ProjectCardView, type CardHandlers } from './project_card_view'
import type { VisibleCardColumn } from './use_card_view_columns'
import { useCardColumnCards } from './use_card_column_cards'

const MIN_COLUMN_WIDTH = 200
const MAX_COLUMN_WIDTH = 320

interface CardColumnProps extends CardHandlers {
    cardTypes: CardTypeConfig[]
    column: VisibleCardColumn
    isMobile: boolean
}

/** One status column: a polished droppable stack with header metadata and an empty target. */
export function CardColumn(props: CardColumnProps) {
    const {
        cardTypes, column, isMobile,
        ...handlers
    } = props
    const cardPaths = useCardColumnCards(column.status)
    const subscribe = useCallback(
        (listener: () => void) => cardDragDropService.subscribeColumn(column.status, listener),
        [column.status],
    )
    const getSnapshot = useCallback(
        () => cardDragDropService.getColumnPreview(column.status),
        [column.status],
    )
    const dropPreview = useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
    const dropPreviewHeight = dropPreview?.dropPreviewHeight ?? null
    const dropPreviewIndex = dropPreview?.dropPreviewIndex ?? null
    const columnLabel = column.status || 'Unassigned'
    const handleAddCard = () => {
        requestOpenNewCardDialog(column.status)
    }
    const dropPlaceholder = (
        <Box
            aria-label="Card drop position"
            key="drop-preview"
            sx={{
                bgcolor: 'action.selected',
                border: '1.5px dashed',
                borderColor: 'primary.main',
                borderRadius: 1.25,
                minHeight: dropPreviewHeight ?? 107,
            }}
        />
    )
    const cardElements: ReactNode[] = []
    for (let index = 0; index <= cardPaths.length; index += 1) {
        if (dropPreviewIndex === index) cardElements.push(dropPlaceholder)
        const cardPath = cardPaths[index]
        if (!cardPath) continue

        cardElements.push(
            <ProjectCardView
                key={cardPath}
                cardPath={cardPath}
                cardTypes={cardTypes}
                {...handlers}
            />,
        )
    }

    return (
        <Paper
            aria-label={`${columnLabel} column`}
            sx={{
                bgcolor: 'action.hover',
                borderRadius: 1.5,
                display: 'flex',
                flex: isMobile ? '0 0 auto' : 1,
                flexDirection: 'column',
                gap: 1,
                maxWidth: isMobile ? '100%' : MAX_COLUMN_WIDTH,
                minWidth: isMobile ? '100%' : MIN_COLUMN_WIDTH,
                p: 1,
            }}
        >
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1, minHeight: 34, pl: 1, pr: 0.5 }}>
                <Box sx={{ bgcolor: column.color, borderRadius: '3px', flexShrink: 0, height: 8, width: 8 }} />
                <Typography
                    component="h2"
                    sx={{ color: 'text.secondary', fontSize: 12, fontWeight: 700, letterSpacing: 0.6, textTransform: 'uppercase' }}
                >
                    {columnLabel}
                </Typography>
                <Chip
                    label={cardPaths.length}
                    size="small"
                    sx={{ bgcolor: 'background.paper', border: 1, borderColor: 'divider', fontSize: 11, height: 20 }}
                />
                <Box sx={{ flex: 1 }} />
                <Tooltip title="New card">
                    <IconButton aria-label={`Add card from ${columnLabel} column`} onClick={handleAddCard} size="small" sx={{ height: 26, width: 26 }}>
                        <Plus sx={{ fontSize: 16 }} />
                    </IconButton>
                </Tooltip>
            </Box>
            <SortableContext items={cardPaths} strategy={verticalListSortingStrategy}>
                {cardElements}
                {cardPaths.length === 0 && dropPreviewIndex === null ? (
                    <Box
                        sx={{
                            border: '1.5px dashed',
                            borderColor: 'divider',
                            borderRadius: 1.25,
                            color: 'text.disabled',
                            fontSize: 12,
                            p: 2,
                            textAlign: 'center',
                        }}
                    >
                        Drop a card here
                    </Box>
                ) : null}
                <CardColumnEndDropTarget status={column.status} />
            </SortableContext>
        </Paper>
    )
}

import { Box } from '@mui/material'
import { useRef } from 'react'
import type { PointerEvent, RefObject } from 'react'

const SCROLL_ZONE_WIDTH = 40

interface CardViewScrollZonesProps {
    scrollContainerRef: RefObject<HTMLDivElement | null>
}

interface ScrollGesture {
    clientY: number
    pointerId: number
}

interface CardViewScrollZoneProps extends CardViewScrollZonesProps {
    edge: 'left' | 'right'
}

/** Transparent mobile edge zone that converts pointer movement into card-column scrolling. */
function CardViewScrollZone(props: CardViewScrollZoneProps) {
    const { edge, scrollContainerRef } = props
    const gestureRef = useRef<ScrollGesture | null>(null)

    const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
        gestureRef.current = { clientY: event.clientY, pointerId: event.pointerId }
        event.currentTarget.setPointerCapture?.(event.pointerId)
    }

    const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
        const gesture = gestureRef.current
        if (!gesture || gesture.pointerId !== event.pointerId) return

        const scrollContainer = scrollContainerRef.current
        if (!scrollContainer) throw new Error('Missing card columns scroll container')

        scrollContainer.scrollTop += gesture.clientY - event.clientY
        gesture.clientY = event.clientY
    }

    const clearGesture = (event: PointerEvent<HTMLDivElement>) => {
        if (gestureRef.current?.pointerId !== event.pointerId) return

        gestureRef.current = null
        event.currentTarget.releasePointerCapture?.(event.pointerId)
    }

    return (
        <Box
            aria-hidden
            data-testid={`${edge}-card-scroll-zone`}
            onPointerCancel={clearGesture}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={clearGesture}
            sx={{
                bottom: 0,
                position: 'absolute',
                [edge]: 0,
                top: 0,
                touchAction: 'none',
                width: SCROLL_ZONE_WIDTH,
                zIndex: 2,
            }}
        />
    )
}

/** Mobile-only pair of card-view edge scroll zones. */
export function CardViewScrollZones(props: CardViewScrollZonesProps) {
    return (
        <>
            <CardViewScrollZone edge="left" {...props} />
            <CardViewScrollZone edge="right" {...props} />
        </>
    )
}

